package org.sleepwell.app;
import android.content.Context;import java.util.*;import java.util.concurrent.*;
/** Retained one-job owner; no Activity retained, no view touched off-main. */
final class TagJobs {
 static final Map<Records.Factory,Job> jobs=new IdentityHashMap<>();static synchronized Job get(Context c,Records.Factory factory){return jobs.computeIfAbsent(factory,k->new Job(c.getApplicationContext(),factory));}
 static final class State {State(State old){busy=true;records=old.records;result=old.result;error="";now=old.now;impacts=old.impacts;signatures=old.signatures;}final boolean busy;final List<RecordEntry> records;final String result,error;final Map<String,TagImpact> impacts;final Map<String,String> signatures;final long now;State(boolean busy,List<RecordEntry> records,String result,String error,long now){this.busy=busy;this.records=List.copyOf(records);this.result=result;this.error=error;this.now=now;Map<String,TagImpact> calculated=new TreeMap<>();Map<String,String> signatures=new TreeMap<>();for(String tag:TagImpact.names(records)){calculated.put(tag,new TagImpact(records,tag,now));signatures.put(tag,TagRecords.signature(records,tag));}this.impacts=Collections.unmodifiableMap(calculated);this.signatures=Collections.unmodifiableMap(signatures);}}
 static final class Job {final Context app;final Records.Factory factory;final ExecutorService worker=Executors.newSingleThreadExecutor();volatile State state=new State(false,List.of(),"","",System.currentTimeMillis());Job(Context c,Records.Factory f){app=c;factory=f;}synchronized void start(String tag,String rename,String expected){if(state.busy)return;State old=state;state=new State(old);worker.execute(()->{String message=old.result,error="";List<RecordEntry> records=old.records;long now=System.currentTimeMillis();try(Store store=factory.open(app)){if(tag!=null){int n=TagRecords.change(store,tag,rename,expected,now);message=n+" records updated.";}records=Records.all(store);}catch(Exception failure){error=failure.getMessage()==null?"Tags could not be read or saved.":failure.getMessage();}state=new State(false,records,message,error,now);});}void inspect(){start(null,null,null);}void change(String tag,String rename,String expected){start(tag,rename,expected);}}
 static void drain(Records.Factory f)throws Exception{Job j;synchronized(TagJobs.class){j=jobs.get(f);}if(j!=null)j.worker.submit(()->{}).get(10,TimeUnit.SECONDS);}static synchronized void forget(Records.Factory f){Job j=jobs.remove(f);if(j!=null){if(j.state.busy)throw new IllegalStateException("Tag work is active");j.worker.shutdown();}}
 private TagJobs(){}
}
